import sys

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    by_x = [[] for _ in range(n + 1)]
    pos = 2
    for _ in range(m):
        l, r, x = data[pos], data[pos + 1], data[pos + 2]
        pos += 3
        by_x[x].append((l, r))

    # For a prospective subproblem [l,r], choosing x as its maximum
    # violates a condition exactly when some condition for x is contained
    # in [l,r]. threshold[x][l] stores the least such right endpoint.
    inf = n + 1
    threshold = [[inf] * (n + 2) for _ in range(n + 1)]
    for x in range(1, n + 1):
        at_left = [inf] * (n + 1)
        for l, r in by_x[x]:
            if r < at_left[l]:
                at_left[l] = r
        best = inf
        row = threshold[x]
        for l in range(n, 0, -1):
            if at_left[l] < best:
                best = at_left[l]
            row[l] = best

    # Binomial coefficients for interleaving the two sides of a maximum.
    choose = [[0] * (n + 1) for _ in range(n + 1)]
    choose[0][0] = 1
    for a in range(1, n + 1):
        choose[a][0] = choose[a][a] = 1
        for b in range(1, a):
            choose[a][b] = (choose[a - 1][b - 1] + choose[a - 1][b]) % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            row_threshold = threshold
            total = 0
            for x in range(l, r + 1):
                if row_threshold[x][l] <= r:
                    continue
                left_len = x - l
                total += dp[l][x - 1] * dp[x + 1][r] % MOD * choose[length - 1][left_len]
            dp[l][r] = total % MOD

    print(dp[1][n])

if __name__ == '__main__':
    solve()

