import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]

    factors = []
    all_primes = set()
    for value in values:
        x = value
        f = {}
        d = 2
        while d * d <= x:
            if x % d == 0:
                e = 0
                while x % d == 0:
                    x //= d
                    e += 1
                f[d] = e
                all_primes.add(d)
            d += 1
        if x > 1:
            f[x] = 1
            all_primes.add(x)
        factors.append(f)

    answer = 1
    for prime in all_primes:
        exponents = [f.get(prime, 0) for f in factors]
        height_limit = sum(exponents)
        powers = [pow(prime, h, MOD) for h in range(height_limit + 1)]

        # dp0[h]: weight of paths at height h which have not visited 0;
        # dp1[h]: weight of paths at height h which have visited 0.
        # The weight is prime^(sum of vertex heights so far).
        dp0 = [0] * (height_limit + 1)
        dp1 = [0] * (height_limit + 1)
        dp1[0] = 1
        for h in range(1, height_limit + 1):
            dp0[h] = powers[h]  # arbitrary initial height, before any edge

        for e in exponents:
            ndp0 = [0] * (height_limit + 1)
            ndp1 = [0] * (height_limit + 1)
            if e == 0:
                for h in range(height_limit + 1):
                    w = powers[h]
                    if dp0[h]:
                        ndp0[h] = dp0[h] * w % MOD
                    if dp1[h]:
                        ndp1[h] = dp1[h] * w % MOD
            else:
                for h in range(height_limit + 1):
                    a = dp0[h]
                    b = dp1[h]
                    if not a and not b:
                        continue
                    w = h - e
                    if w >= 0:
                        pw = powers[w]
                        if a:
                            ndp1[w] = (ndp1[w] + a * pw) % MOD
                        if b:
                            ndp1[w] = (ndp1[w] + b * pw) % MOD
                    w = h + e
                    if w <= height_limit:
                        pw = powers[w]
                        if a:
                            ndp0[w] = (ndp0[w] + a * pw) % MOD
                        if b:
                            ndp1[w] = (ndp1[w] + b * pw) % MOD
            dp0, dp1 = ndp0, ndp1

        local_sum = sum(dp1) % MOD
        answer = answer * local_sum % MOD

    print(answer)

if __name__ == '__main__':
    main()

