def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if phi[p] == p:
            for k in range(p, mx + 1, p):
                phi[k] -= phi[k] // p

    divisors = [[] for _ in range(mx + 1)]
    for d in range(1, mx + 1):
        for x in range(d, mx + 1, d):
            divisors[x].append(d)

    weighted_sums = [0] * (mx + 1)
    answer = 0
    weight = 1
    output = []
    for x in a:
        divs = divisors[x]
        contribution = 0
        for d in divs:
            contribution += phi[d] * weighted_sums[d]
        contribution %= MOD
        answer = (2 * answer + contribution) % MOD
        output.append(str(answer))

        for d in divs:
            value = weighted_sums[d] + weight
            if value >= MOD:
                value -= MOD
            weighted_sums[d] = value
        weight = weight * 2 % MOD

    sys.stdout.write('\n'.join(output))

