from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # For a pair (a, b), with a < b, once the right endpoint reaches b,
        # a valid subarray must start after a. At each right endpoint, only
        # the largest active a matters.
        by_right = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        # Keep the two largest active left endpoints, counting distinct pairs.
        first_value, first_id = 0, -1
        second_value = 0
        gains = [0] * m
        total = 0

        for right in range(1, n + 1):
            for value, pair_id in by_right[right]:
                if value > first_value:
                    second_value = first_value
                    first_value, first_id = value, pair_id
                elif value > second_value:
                    second_value = value

            total += right - first_value
            if first_id != -1:
                # Removing the unique largest constraint increases valid
                # starts by the difference to the next largest constraint.
                gains[first_id] += first_value - second_value

        return total + max(gains)

