import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    roads = []
    for _ in range(m):
        a, b, c = next(it)-1, next(it)-1, next(it)
        roads.append((a, b, c))
    queries = []
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            queries.append((1, next(it)-1))
        else:
            queries.append((2, next(it)-1, next(it)-1))

    inf = 10**30
    answers = []
    block_size = 30
    pos = 0
    closed = [False] * m
    while pos < q:
        end = pos
        deletions = 0
        while end < q:
            if queries[end][0] == 1:
                if deletions == block_size:
                    break
                deletions += 1
            end += 1
        special_ids = [queries[j][1] for j in range(pos, end) if queries[j][0] == 1]
        terminals = sorted({v for i in special_ids for v in roads[i][:2]})
        tcount = len(terminals)
        index = {v: i for i, v in enumerate(terminals)}
        base = [[inf] * n for _ in range(n)]
        for i in range(n):
            base[i][i] = 0
        excluded = set(special_ids)
        for rid, (u, v, w) in enumerate(roads):
            if rid not in excluded and not closed[rid]:
                if w < base[u][v]:
                    base[u][v] = base[v][u] = w
        for k in range(n):
            rowk = base[k]
            for i in range(n):
                dik = base[i][k]
                if dik == inf:
                    continue
                rowi = base[i]
                for j in range(n):
                    z = dik + rowk[j]
                    if z < rowi[j]:
                        rowi[j] = z

        active = set(special_ids)

        def rebuild():
            cd = [[base[u][v] for v in terminals] for u in terminals]
            for rid in active:
                u, v, w = roads[rid]
                a, b = index[u], index[v]
                if w < cd[a][b]:
                    cd[a][b] = cd[b][a] = w
            for k in range(tcount):
                rk = cd[k]
                for i in range(tcount):
                    dik = cd[i][k]
                    if dik == inf:
                        continue
                    ri = cd[i]
                    for j in range(tcount):
                        z = dik + rk[j]
                        if z < ri[j]:
                            ri[j] = z
            L = [[inf] * tcount for _ in range(n)]
            for x in range(n):
                lx = L[x]
                bx = base[x]
                for a in range(tcount):
                    d = bx[terminals[a]]
                    if d == inf:
                        continue
                    ra = cd[a]
                    for b in range(tcount):
                        z = d + ra[b]
                        if z < lx[b]:
                            lx[b] = z
            return L

        L = rebuild()
        for j in range(pos, end):
            query = queries[j]
            if query[0] == 1:
                rid = query[1]
                closed[rid] = True
                active.remove(rid)
                L = rebuild()
            else:
                _, x, y = query
                ans = base[x][y]
                for b, v in enumerate(terminals):
                    z = L[x][b] + base[v][y]
                    if z < ans:
                        ans = z
                answers.append(str(-1 if ans == inf else ans))
        pos = end
    sys.stdout.write('\n'.join(answers))

if __name__ == '__main__':
    main()

