class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # ways[r][j] = C(r, j)
        ways = [[1] + [0] * r for r in range(n + 1)]
        for r in range(1, n + 1):
            for j in range(1, r):
                ways[r][j] = (ways[r - 1][j - 1] + ways[r - 1][j]) % MOD
            ways[r][r] = 1

        good = [False] * (n + 1)
        for t in range(1, n + 1):
            steps = 0
            v = t
            while v != 1:
