from collections import deque
import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    graph = [row.decode() for row in data[1:1 + n]]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-':
                c = ord(ch) - ord('a')
                outgoing[i][c].append(j)
                incoming[j][c].append(i)

    dist = [[-1] * n for _ in range(n)]
    queue = deque()
    # Palindromes with zero or one edge are the centers of the construction.
    for i in range(n):
        dist[i][i] = 0
        queue.append((i, i))
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-' and dist[i][j] == -1:
                dist[i][j] = 1
                queue.append((i, j))

    # Add matching outer edges to both ends of an already-palindromic path.
    while queue:
        u, v = queue.popleft()
        nd = dist[u][v] + 2
        for c in range(26):
            left = incoming[u][c]
            right = outgoing[v][c]
            for x in left:
                row = dist[x]
                for y in right:
                    if row[y] == -1:
                        row[y] = nd
                        queue.append((x, y))

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

