import math

N = int(sys.stdin.buffer.readline())

# Since N = d * (3*y^2 + 3*d*y + d^2), where d = x-y,
# we have d^3 <= N. Find floor(cuberoot(N)) exactly.
lo, hi = 0, 1
while hi ** 3 <= N:
    hi *= 2
while lo + 1 < hi:
    mid = (lo + hi) // 2
    if mid ** 3 <= N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d:
        continue
    q = N // d
    # 4*q - d^2 = 3*(2*y+d)^2
    a = 4 * q - d * d
    if a < 0 or a % 3:
        continue
    v = a // 3
    t = math.isqrt(v)
    if t * t != v or (t - d) % 2:
        continue
    y = (t - d) // 2
    if y > 0:
        print(y + d, y)
        break
else:
    print(-1)

