from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Clockwise order in screen coordinates: SE, SW, NW, NE.
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        answer = 0

        for d, (dr, dc) in enumerate(dirs):
            row_order = range(n) if dr == 1 else range(n - 1, -1, -1)
            # Maximum straight-path length ending at each cell, separated by parity.
            straight_even = [[0] * m for _ in range(n)]
            straight_odd = [[0] * m for _ in range(n)]

            for i in row_order:
                for j in range(m):
                    if grid[i][j] == 1:
                        straight_odd[i][j] = max(straight_odd[i][j], 1)
                    for length in (straight_even[i][j], straight_odd[i][j]):
                        if not length:
                            continue
                        answer = max(answer, length)
                        ni, nj = i + dr, j + dc
                        expected = 2 if length % 2 else 0
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == expected:
                            target = straight_odd if (length + 1) % 2 else straight_even
                            target[ni][nj] = max(target[ni][nj], length + 1)

            # A clockwise turn is now taken; propagate along only that direction.
            tr, tc = dirs[(d + 1) % 4]
            turned_even = [[0] * m for _ in range(n)]
            turned_odd = [[0] * m for _ in range(n)]
            for i in range(n):
                for j in range(m):
                    for length in (straight_even[i][j], straight_odd[i][j]):
                        if length:
                            ni, nj = i + tr, j + tc
                            expected = 2 if length % 2 else 0
                            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == expected:
                                target = turned_odd if (length + 1) % 2 else turned_even
                                target[ni][nj] = max(target[ni][nj], length + 1)

            turned_rows = range(n) if tr == 1 else range(n - 1, -1, -1)
            for i in turned_rows:
                for j in range(m):
                    for length in (turned_even[i][j], turned_odd[i][j]):
                        if not length:
                            continue
                        answer = max(answer, length)
                        ni, nj = i + tr, j + tc
                        expected = 2 if length % 2 else 0
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == expected:
                            target = turned_odd if (length + 1) % 2 else turned_even
                            target[ni][nj] = max(target[ni][nj], length + 1)

        return answer

