class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        remaining = list(range(1, n + 1))
        result = []
        previous_parity = None

        for pos in range(n):
            chosen = False
            for value in remaining:  # ascending order gives lexicographic blocks
                parity = value % 2
                if previous_parity is not None and parity == previous_parity:
                    continue

                left_odds = odds - (parity == 1)
                left_evens = evens - (parity == 0)
                slots = n - pos - 1

                if slots == 0:
                    ways = int(left_odds == 0 and left_evens == 0)
                else:
                    next_parity = 1 - parity
                    needed_odds = (slots + 1) // 2 if next_parity == 1 else slots // 2
                    needed_evens = slots - needed_odds
                    if left_odds == needed_odds and left_evens == needed_evens:
                        ways = fact[left_odds] * fact[left_evens]
                    else:
                        ways = 0

                if k > ways:
                    k -= ways
                else:
                    result.append(value)
                    remaining.remove(value)
                    if parity == 1:
                        odds -= 1
                    else:
                        evens -= 1
                    previous_parity = parity
                    chosen = True
                    break

            if not chosen:
                return []

        return result

