class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            if i == n - 1 - i:
                c = pow(10, i, k)
            else:
                c = (pow(10, i, k) + pow(10, n - 1 - i, k)) % k
            coeff.append(c)

        # suffix[i] is a bitset of the residues obtainable using digits i onward.
        suffix = [0] * (m + 1)
        suffix[m] = 1
        for i in range(m - 1, -1, -1):
            old = suffix[i + 1]
            reachable = 0
            for residue in range(k):
                if (old >> residue) & 1:
                    for digit in range(10):
                        reachable |= 1 << ((residue + digit * coeff[i]) % k)
            suffix[i] = reachable

        chosen = []
        remainder = 0
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-remainder - digit * c) % k
                if (suffix[i + 1] >> needed) & 1:
                    chosen.append(str(digit))
                    remainder = (remainder + digit * c) % k
                    break

        left = ''.join(chosen)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

