from array import array

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        # next greater element to the right (strictly greater)
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        levels = n.bit_length()
        jumps = [array('i', nxt)]
        costs = [array('q', (
            nums[i] * (nxt[i] - i) - (pref[nxt[i]] - pref[i])
            for i in range(n)
        ))]

        # A jump consumes complete constant-prefix-maximum blocks.
        for _ in range(1, levels):
            prev_jump, prev_cost = jumps[-1], costs[-1]
            cur_jump = array('i', [n]) * n
            cur_cost = array('q', [0]) * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    cur_jump[i] = prev_jump[mid]
                    cur_cost[i] = prev_cost[i] + prev_cost[mid]
                else:
                    cur_cost[i] = prev_cost[i]
            jumps.append(cur_jump)
            costs.append(cur_cost)

        answer = 0
        for start in range(n):
            pos = start
            spent = 0
            # Consume as many whole blocks as the budget permits.
            for b in range(levels - 1, -1, -1):
                if pos < n and jumps[b][pos] < n and spent + costs[b][pos] <= k:
                    spent += costs[b][pos]
                    pos = jumps[b][pos]

            if pos == n:
                answer += n - start
                continue

            # The affordable endpoint lies in this one remaining block.
            lo, hi = pos, nxt[pos] - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                extra = nums[pos] * (mid - pos + 1) - (pref[mid + 1] - pref[pos])
                if spent + extra <= k:
                    lo = mid
                else:
                    hi = mid - 1
            answer += lo - start + 1

        return answer

