from functools import lru_cache
import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, l = data[:3]
    values = data[3:]
    total = n + m + l
    all_cards = (1 << total) - 1
    first_hand = (1 << n) - 1
    second_hand = ((1 << (n + m)) - 1) ^ first_hand

    @lru_cache(None)
    def winning(h1, h2, turn):
        hand = h1 if turn == 0 else h2
        if hand == 0:
            return False

        other_hand = h2 if turn == 0 else h1
        table = all_cards ^ (h1 | h2)

        for i, value in enumerate(values):
            bit = 1 << i
            if not (hand & bit):
                continue

            remaining_hand = hand ^ bit
            # The played card is on the table; taking a card is optional.
            available = table | bit
            options = [-1]
            options.extend(j for j, other_value in enumerate(values)
                           if (available >> j) & 1 and other_value < value)

            for j in options:
                if turn == 0:
                    next_h1, next_h2 = remaining_hand, other_hand
                else:
                    next_h1, next_h2 = other_hand, remaining_hand

                if j >= 0:
                    if turn == 0:
                        next_h1 |= 1 << j
                    else:
                        next_h2 |= 1 << j

                if not winning(next_h1, next_h2, 1 - turn):
                    return True
        return False

    print("Takahashi" if winning(first_hand, second_hand, 0) else "Aoki")

if __name__ == "__main__":
    main()

