from bisect import bisect_left, bisect_right

class Solution:
    def _occurrences(self, text: str, pattern: str):
        n, m = len(text), len(pattern)
        if m == 0:
            return list(range(n + 1))

        prefix = [0] * m
        j = 0
        for i in range(1, m):
            while j and pattern[i] != pattern[j]:
                j = prefix[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
            prefix[i] = j

        found = []
        j = 0
        for i, ch in enumerate(text):
            while j and ch != pattern[j]:
                j = prefix[j - 1]
            if ch == pattern[j]:
                j += 1
            if j == m:
                found.append(i - m + 1)
                j = prefix[j - 1]
        return found

    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first, middle, last = p.split('*')
        first_pos = self._occurrences(s, first)
        middle_pos = self._occurrences(s, middle)
        last_pos = self._occurrences(s, last)

        best = len(s) + 1
        for mid in middle_pos:
            # Latest first-piece occurrence ending no later than middle.
            i = bisect_right(first_pos, mid - len(first)) - 1
            # Earliest last-piece occurrence starting after middle.
            j = bisect_left(last_pos, mid + len(middle))
            if i >= 0 and j < len(last_pos):
                best = min(best, last_pos[j] + len(last) - first_pos[i])

        return best if best <= len(s) else -1

