class Solution:
    def _occ(self, text, pat):
        n, m = len(text), len(pat)
        if not m:
            return list(range(n + 1))
        # KMP
        pi = [0] * m
        j = 0
        for i in range(1, m):
            while j and pat[i] != pat[j]:
                j = pi[j-1]
            if pat[i] == pat[j]:
                j += 1
            pi[i] = j
        out = []
        j = 0
        for i, ch in enumerate(text):
            while j and ch != pat[j]:
                j = pi[j-1]
            if ch == pat[j]:
                j += 1
            if j == m:
                out.append(i-m+1)
                j = pi[j-1]
        return out
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        aa, bb, cc = self._occ(s,a), self._occ(s,b), self._occ(s,c)
        ans = len(s)+1
        for x in bb:
            ia = bisect_right(aa, x-len(a))-1
            ic = bisect_left(cc, x+len(b))
            if ia >= 0 and ic < len(cc):
                ans = min(ans, cc[ic]+len(c)-aa[ia])
        return ans if ans <= len(s) else -1

