class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Build the specified postorder string and record each subtree's interval.
        postorder = []
        left = [0] * n
        right = [0] * n
        stack = [(0, False)]
        while stack:
            x, exiting = stack.pop()
            if not exiting:
                left[x] = len(postorder)
                stack.append((x, True))
                for y in reversed(children[x]):
                    stack.append((y, False))
            else:
                postorder.append(s[x])
                right[x] = len(postorder)

        # Manacher radii for odd- and even-length palindromes.
        odd = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < n and postorder[i - k] == postorder[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        even = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < n and postorder[i - k - 1] == postorder[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        answer = [False] * n
        for i in range(n):
            length = right[i] - left[i]
            if length % 2:
                center = (left[i] + right[i] - 1) // 2
                answer[i] = odd[center] >= length // 2 + 1
            else:
                center = (left[i] + right[i]) // 2
                answer[i] = even[center] >= length // 2
        return answer

