import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        low = 10 ** (digits - 1)
        high = 10 ** digits - 1

        # Sieve primes in the range of values with this number of digits.
        is_prime = [True] * (high + 1)
        is_prime[0] = False
        is_prime[1] = False
        for p in range(2, int(high ** 0.5) + 1):
            if is_prime[p]:
                for value in range(p * p, high + 1, p):
                    is_prime[value] = False

        if is_prime[n] or is_prime[m]:
            return -1

        # Entering a value incurs its value as cost, including the start.
        dist = {n: n}
        queue = [(n, n)]
        while queue:
            cost, value = heapq.heappop(queue)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            place = 1
            while place <= value:
                digit = (value // place) % 10
                if digit > 0:
                    nxt = value - place
                    if nxt >= low and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, float('inf')):
                            dist[nxt] = new_cost
                            heapq.heappush(queue, (new_cost, nxt))
                if digit < 9:
                    nxt = value + place
                    if nxt <= high and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, float('inf')):
                            dist[nxt] = new_cost
                            heapq.heappush(queue, (new_cost, nxt))
                place *= 10

        return -1

