class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq
        length = len(str(n))
        lo = 10 ** (length - 1)
        hi = 10 ** length - 1
        prime = [True] * (hi + 1)
        if hi >= 0:
            prime[0] = False
        if hi >= 1:
            prime[1] = False
        for p in range(2, int(hi ** 0.5) + 1):
            if prime[p]:
                for x in range(p * p, hi + 1, p):
                    prime[x] = False
        if prime[n] or prime[m]:
            return -1
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            cost, x = heapq.heappop(pq)
            if dist[x] != cost:
                continue
            if x == m:
                return cost
            power = 1
            while power <= x:
                digit = (x // power) % 10
                if digit > 0:
                    y = x - power
