from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        # Process suffix-LCP rows in descending i. The rolling rows suffice:
        # lcp(i,j) = 1 + lcp(i+1,j+1) when nums[i] == nums[j].
        answer = 0
        next_row = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            row = [0] * (n + 1)
            for j in range(n - 1, i, -1):
                if nums[i] == nums[j]:
                    row[j] = 1 + next_row[j + 1]

                # First condition: nums1 is a prefix of nums2.
                first = j >= 2 * i and z[i] >= i
                # Second condition: nums2 is a prefix of nums3.
                second = row[j] >= j - i
                if first or second:
                    answer += 1
            next_row = row

        return answer

