import sys

def main():
    data = sys.stdin.buffer.read().split()
    k = int(data[0])
    s = data[1].decode()
    t = data[2].decode()

    if s == t:
        print("Yes")
        return

    n, m = len(s), len(t)
    if abs(n - m) > k:
        print("No")
    elif n == m:
        print("Yes" if sum(a != b for a, b in zip(s, t)) <= k else "No")
    else:
        # For one insertion/deletion, check whether the shorter string is
        # obtainable by skipping at most one character from the longer one.
        if n > m:
            s, t = t, s
        i = j = 0
        skipped = False
        while i < len(s) and j < len(t):
            if s[i] == t[j]:
                i += 1
                j += 1
            elif skipped:
                print("No")
                return
            else:
                skipped = True
                j += 1
        print("Yes")

