def fast(a,b):
    lo=max(x-y for y,(x,z) in zip(a,b)); hi=min(z-y for y,(x,z) in zip(a,b))
    return max(0,hi-lo+1)
def ref(a,b):
    ans=0
    for start in range(min(x for x,z in b),max(z for x,z in b)+1):
        arr=[start+a[i]-a[0] for i in range(len(a))]
        ans+=all(x<=v<=z for v,(x,z) in zip(arr,b))
    return ans
for n in range(2,8):
 for _ in range(1000):
